"""Default-device, in-memory 16 kHz mono signed-16-bit PCM capture."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Protocol


class _InputStream(Protocol):
	def start(self) -> None: ...
	def stop(self) -> None: ...
	def close(self) -> None: ...


class Recorder:
	"""Capture one utterance in RAM; no audio is written to disk."""

	def __init__(self, device: str = "system-default", stream_factory: Callable[..., _InputStream] | None = None) -> None:
		self._device = None if device == "system-default" else device
		self._stream_factory = stream_factory or self._sounddevice_stream
		self._stream: _InputStream | None = None
		self._frames = bytearray()

	@staticmethod
	def _sounddevice_stream(**kwargs: object) -> _InputStream:
		import sounddevice

		return sounddevice.RawInputStream(**kwargs)

	def start(self) -> None:
		if self._stream is not None:
			raise RuntimeError("recording is already active")
		self._frames.clear()
		self._stream = self._stream_factory(
			samplerate=16_000,
			channels=1,
			dtype="int16",
			device=self._device,
			callback=self._on_audio,
		)
		self._stream.start()

	def _on_audio(self, indata: object, frames: int, time_info: object, status: object) -> None:
		if status:
			raise RuntimeError("audio capture reported a device status")
		self._frames.extend(bytes(indata))

	def stop(self) -> bytes:
		stream, self._stream = self._stream, None
		if stream is None:
			raise RuntimeError("recording is not active")
		try:
			stream.stop()
		finally:
			stream.close()
		audio = bytes(self._frames)
		self._frames.clear()
		return audio

	def discard(self) -> None:
		self._frames.clear()


@dataclass(frozen=True)
class AudioInputDevice:
	identifier: str
	name: str


def list_input_devices(query_devices: Callable[[], object] | None = None) -> tuple[AudioInputDevice, ...]:
	if query_devices is None:
		import sounddevice
		query_devices = sounddevice.query_devices
	devices = query_devices()
	return tuple(AudioInputDevice(str(index), str(device["name"])) for index, device in enumerate(devices) if device.get("max_input_channels", 0) > 0)


def microphone_available(preference: str, devices: tuple[AudioInputDevice, ...]) -> bool:
	return bool(devices) if preference == "system-default" else any(device.identifier == preference for device in devices)

"""Default-device, in-memory 16 kHz mono signed-16-bit PCM capture."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Protocol


class _InputStream(Protocol):
	def start(self) -> None: ...
	def stop(self) -> None: ...
	def close(self) -> None: ...


class Recorder:
	"""Capture one utterance in RAM; no audio is written to disk."""

	def __init__(self, device: str = "system-default", stream_factory: Callable[..., _InputStream] | None = None) -> None:
		self._device = None if device == "system-default" else device
		self._stream_factory = stream_factory or self._sounddevice_stream
		self._stream: _InputStream | None = None
		self._frames = bytearray()
		self._capture_error: RuntimeError | None = None

	@staticmethod
	def _sounddevice_stream(**kwargs: object) -> _InputStream:
		import sounddevice

		return sounddevice.RawInputStream(**kwargs)

	def start(self) -> None:
		if self._stream is not None:
			raise RuntimeError("recording is already active")
		self._frames.clear()
		self._capture_error = None
		try:
			self._stream = self._stream_factory(
				samplerate=16_000,
				channels=1,
				dtype="int16",
				device=self._device,
				callback=self._on_audio,
			)
			self._stream.start()
		except Exception:
			self.discard()
			raise

	def _on_audio(self, indata: object, frames: int, time_info: object, status: object) -> None:
		if status:
			self._capture_error = RuntimeError("audio capture reported a device status")
			return
		self._frames.extend(bytes(indata))

	def stop(self) -> bytes:
		stream, self._stream = self._stream, None
		if stream is None:
			raise RuntimeError("recording is not active")
		try:
			stream.stop()
		finally:
			stream.close()
		if self._capture_error is not None:
			self._frames.clear()
			error, self._capture_error = self._capture_error, None
			raise error
		audio = bytes(self._frames)
		self._frames.clear()
		return audio

	def discard(self) -> None:
		stream, self._stream = self._stream, None
		if stream is not None:
			try:
				stream.stop()
			except Exception:
				pass
			try:
				stream.close()
			except Exception:
				pass
		self._frames.clear()
		self._capture_error = None


@dataclass(frozen=True)
class AudioInputDevice:
	identifier: str
	name: str


def list_input_devices(query_devices: Callable[[], object] | None = None) -> tuple[AudioInputDevice, ...]:
	if query_devices is None:
		import sounddevice
		query_devices = sounddevice.query_devices
	devices = query_devices()
	return tuple(AudioInputDevice(str(index), str(device["name"])) for index, device in enumerate(devices) if device.get("max_input_channels", 0) > 0)


def microphone_available(preference: str, devices: tuple[AudioInputDevice, ...]) -> bool:
	return bool(devices) if preference == "system-default" else any(device.identifier == preference for device in devices)

"""Command-line entry point; commands remain content-free by contract."""

from __future__ import annotations

import argparse
import sys
import time
from pathlib import Path

from dictate.asr import WhisperServer
from dictate.audio import Recorder, list_input_devices
from dictate.cleanup import OllamaClient
from dictate.config import Preferences, load_preferences
from dictate.dictionary import global_dictionary_path, terms_for_paths
from dictate.platform import current_platform
from dictate.readiness import LocalReadiness
from dictate.service import DictationService, check_readiness


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="dictate", description="Local-only push-to-talk dictation")
    commands = parser.add_subparsers(dest="command", required=True)
    for name, help_text in (
        ("setup", "check required local setup"),
        ("serve", "start the local dictation service"),
        ("doctor", "run content-free readiness diagnostics"),
        ("devices", "list audio input devices"),
    ):
        command = commands.add_parser(name, help=help_text)
        if name == "serve":
            command.add_argument("--recover", action="store_true", help="print and clear an injected in-process recovery result (test-only)")
    return parser


def preferences_path(home: Path | None = None) -> Path:
    return (home or Path.home()) / ".config" / "dictate" / "preferences.toml"


def _report_readiness(command: str, preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print(f"{command}: configuration or local capability check failed", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"{command}: limitation: {limitation}", file=sys.stderr)
    if not result.ready:
        for failure in result.required_failures:
            print(f"{command}: not ready: {failure}", file=sys.stderr)
        return 1
    print(f"{command}: ready")
    return 0


def _serve(preferences: Preferences) -> int:
    try:
        platform = current_platform()
        result = check_readiness(preferences, LocalReadiness(platform))
    except Exception:
        print("serve: configuration or local capability check failed", file=sys.stderr)
        return 1
    if not result.ready:
        for failure in result.required_failures:
            print(f"serve: not ready: {failure}", file=sys.stderr)
        return 1
    for limitation in result.limitations:
        print(f"serve: limitation: {limitation}", file=sys.stderr)
    try:
        global_terms = terms_for_paths(global_dictionary_path())
    except (OSError, ValueError):
        print("serve: invalid local dictionary", file=sys.stderr)
        return 1
    service = DictationService(
        preferences,
        platform,
        Recorder(preferences.microphone),
        WhisperServer(preferences.asr_endpoint),
        OllamaClient(preferences.ollama_endpoint, preferences.ollama_model),
        status=lambda event: print(f"serve: {event}", file=sys.stderr),
        terms_for_target=lambda _target: global_terms,
    )
    try:
        service.start()
    except Exception:
        service.stop()
        print("serve: could not start local dictation service", file=sys.stderr)
        return 1
    print("serve: ready", file=sys.stderr)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        return 0
    finally:
        service.stop()


def main(argv: list[str] | None = None, *, recovery: object | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "serve" and args.recover:
        from dictate.service import DEFAULT_RECOVERY

        result = (recovery or DEFAULT_RECOVERY).take()
        if result is None:
            print("no recovery result is available", file=sys.stderr)
            return 1
        print(result)
        return 0
    try:
        preferences = load_preferences(preferences_path())
    except (OSError, ValueError):
        print(f"{args.command}: invalid local preferences", file=sys.stderr)
        return 1
    if args.command == "devices":
        try:
            devices = list_input_devices()
        except Exception:
            print("devices: could not inspect local audio inputs", file=sys.stderr)
            return 1
        if not devices:
            print("devices: no local audio inputs are available", file=sys.stderr)
            return 1
        for device in devices:
            print(f"{device.identifier}\t{device.name}")
        return 0
    if args.command in ("setup", "doctor"):
        return _report_readiness(args.command, preferences)
    return _serve(preferences)

"""Newline-delimited local vocabulary loading and deterministic merging."""

from __future__ import annotations

from pathlib import Path

MAX_TERMS = 128
MAX_TERM_LENGTH = 120


def global_dictionary_path(home: Path | None = None) -> Path:
    return (home or Path.home()) / ".config" / "dictate" / "dictionary.txt"


def project_dictionary_path(project_root: Path) -> Path:
    return project_root / ".dictate" / "dictionary.txt"


def load_dictionary(path: Path) -> dict[str, str]:
    """Return normalized spelling keys mapped to their user-authored spelling."""
    if not path.exists():
        return {}
    entries: dict[str, str] = {}
    for line_number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        term = raw.strip()
        if not term:
            continue
        if "\x00" in term:
            raise ValueError(f"dictionary contains an invalid term on line {line_number}")
        entries[term.casefold()] = term
    return entries


def merge_dictionaries(global_terms: dict[str, str], project_terms: dict[str, str] | None = None) -> tuple[str, ...]:
    """Merge global terms first; project terms override matching spellings."""
    merged = dict(global_terms)
    merged.update(project_terms or {})
    return tuple(merged[key] for key in sorted(merged) if len(merged[key]) <= MAX_TERM_LENGTH)[:MAX_TERMS]


def terms_for_paths(global_path: Path, project_root: Path | None = None) -> tuple[str, ...]:
    """Load a bounded, deterministic session snapshot; project spellings take precedence."""
    project = load_dictionary(project_dictionary_path(project_root)) if project_root else None
    return merge_dictionaries(load_dictionary(global_path), project)

"""Newline-delimited local vocabulary loading and deterministic merging."""

from __future__ import annotations

from pathlib import Path

MAX_TERMS = 128
MAX_TERM_LENGTH = 120


def global_dictionary_path(home: Path | None = None) -> Path:
    return (home or Path.home()) / ".config" / "dictate" / "dictionary.txt"


def project_dictionary_path(project_root: Path) -> Path:
    return project_root / ".dictate" / "dictionary.txt"


def load_dictionary(path: Path) -> dict[str, str]:
    """Return normalized spelling keys mapped to their user-authored spelling."""
    if not path.exists():
        return {}
    entries: dict[str, str] = {}
    line_numbers: dict[str, int] = {}
    for line_number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        term = raw.strip()
        if not term:
            continue
        if "\x00" in term:
            raise ValueError(f"dictionary contains an invalid term on line {line_number}")
        normalized = term.casefold()
        if normalized in entries:
            raise ValueError(f"dictionary contains duplicate terms on lines {line_numbers[normalized]} and {line_number}")
        entries[normalized] = term
        line_numbers[normalized] = line_number
    return entries


def merge_dictionaries(global_terms: dict[str, str], project_terms: dict[str, str] | None = None) -> tuple[str, ...]:
    """Merge global terms first; project terms override matching spellings."""
    merged = dict(global_terms)
    merged.update(project_terms or {})
    return tuple(merged[key] for key in sorted(merged) if len(merged[key]) <= MAX_TERM_LENGTH)[:MAX_TERMS]


def terms_for_paths(global_path: Path, project_root: Path | None = None) -> tuple[str, ...]:
    """Load a bounded, deterministic session snapshot; project spellings take precedence."""
    project = load_dictionary(project_dictionary_path(project_root)) if project_root else None
    return merge_dictionaries(load_dictionary(global_path), project)

"""Platform-specific adapters isolated behind a narrow contract."""

import sys

from dictate.platform.base import Capability, PlatformAdapter, TargetSnapshot


def current_platform() -> PlatformAdapter:
	"""Return the supported adapter for this host, or fail before recording."""
	if sys.platform == "darwin":
		from dictate.platform.macos import MacOSAdapter

		return MacOSAdapter()
	if sys.platform == "win32":
		from dictate.platform.windows import WindowsAdapter

		return WindowsAdapter()
	if sys.platform.startswith("linux"):
		from dictate.platform.linux import LinuxAdapter

		return LinuxAdapter()
	raise RuntimeError(f"unsupported operating system: {sys.platform}")


__all__ = ("Capability", "PlatformAdapter", "TargetSnapshot", "current_platform")

"""Concrete, content-free readiness checks for the local runtime boundaries."""

from __future__ import annotations

from collections.abc import Callable

from dictate.asr import WhisperServer
from dictate.audio import AudioInputDevice, list_input_devices, microphone_available
from dictate.cleanup import OllamaClient
from dictate.platform.base import Capability, PlatformAdapter


class LocalReadiness:
    """Check installed local capabilities without recording or handling user content."""

    def __init__(
        self,
        platform: PlatformAdapter,
        *,
        devices: Callable[[], tuple[AudioInputDevice, ...]] = list_input_devices,
        asr_factory: Callable[[str], WhisperServer] = WhisperServer,
        cleanup_factory: Callable[[str, str], OllamaClient] = OllamaClient,
    ) -> None:
        self._platform = platform
        self._devices = devices
        self._asr_factory = asr_factory
        self._cleanup_factory = cleanup_factory

    def asr_ready(self, endpoint: str) -> Capability:
        try:
            available = self._asr_factory(endpoint).ready()
        except Exception:
            available = False
        return Capability(available, None if available else "start the local whisper.cpp server and verify its loopback endpoint")

    def ollama_model_ready(self, endpoint: str, model: str) -> Capability:
        try:
            available = self._cleanup_factory(endpoint, model).ready()
        except Exception:
            available = False
        return Capability(available, None if available else "start local Ollama and acquire the configured model")

    def microphone_ready(self, device: str) -> Capability:
        permission = self._platform.microphone_permission()
        if not permission.available:
            return permission
        try:
            available = microphone_available(device, self._devices())
        except Exception:
            available = False
        return Capability(available, None if available else "connect or select an available microphone")

    def trigger_ready(self, trigger: str) -> Capability:
        return self._platform.trigger_permission()

    def placement_ready(self) -> Capability:
        return self._platform.placement_permission()

    def context_ready(self) -> Capability:
        return self._platform.context_permission()

"""Ephemeral, single-session dictation state machine."""
from __future__ import annotations
from dataclasses import dataclass from enum import StrEnum
class SessionState(StrEnum): IDLE = "idle" RECORDING = "recording" RECOGNIZING = "recognizing" CLEANING = "cleaning" VALIDATING_TARGET = "validating-target" INSERTED = "inserted" RECOVERY = "recovery" FAILED = "failed"
_TERMINAL = frozenset({SessionState.INSERTED, SessionState.RECOVERY, SessionState.FAILED}) _ALLOWED = { SessionState.IDLE: {SessionState.RECORDING}, SessionState.RECORDING: {SessionState.RECOGNIZING, SessionState.FAILED}, SessionState.RECOGNIZING: {SessionState.CLEANING, SessionState.FAILED}, SessionState.CLEANING: {SessionState.VALIDATING_TARGET, SessionState.FAILED}, SessionState.VALIDATING_TARGET: {SessionState.INSERTED, SessionState.RECOVERY, SessionState.FAILED}, }
@dataclass class DictationSession: state: SessionState = SessionState.IDLE audio: bytes | None = None transcript: str | None = None context: str | None = None prompt: str | None = None output: str | None = None
def transition(self, next_state: SessionState) -> None: if next_state not in _ALLOWED.get(self.state, set()): raise ValueError(f"cannot transition from {self.state} to {next_state}") self.state = next_state if next_state in _TERMINAL: self.clear_content()
def fail(self) -> None: if self.state in _TERMINAL or self.state is SessionState.IDLE: raise ValueError(f"cannot fail from {self.state}") self.state = SessionState.FAILED self.clear_content()
def clear_content(self) -> None: self.audio = self.transcript = self.context = self.prompt = self.output = None

"""Ephemeral, single-session dictation state machine."""
from __future__ import annotations
from dataclasses import dataclass from enum import StrEnum
class SessionState(StrEnum): IDLE = "idle" RECORDING = "recording" RECOGNIZING = "recognizing" CLEANING = "cleaning" VALIDATING_TARGET = "validating-target" INSERTED = "inserted" RECOVERY = "recovery" FAILED = "failed"
_TERMINAL = frozenset({SessionState.INSERTED, SessionState.RECOVERY, SessionState.FAILED}) _ALLOWED = { SessionState.IDLE: {SessionState.RECORDING}, SessionState.RECORDING: {SessionState.RECOGNIZING, SessionState.FAILED}, SessionState.RECOGNIZING: {SessionState.CLEANING, SessionState.FAILED}, SessionState.CLEANING: {SessionState.VALIDATING_TARGET, SessionState.FAILED}, SessionState.VALIDATING_TARGET: {SessionState.INSERTED, SessionState.RECOVERY, SessionState.FAILED}, }
@dataclass class DictationSession: state: SessionState = SessionState.IDLE audio: bytes | None = None transcript: str | None = None context: str | None = None prompt: str | None = None output: str | None = None
def transition(self, next_state: SessionState) -> None: if next_state not in _ALLOWED.get(self.state, set()): raise ValueError(f"cannot transition from {self.state} to {next_state}") self.state = next_state if next_state in _TERMINAL: self.clear_content()
def fail(self) -> None: if self.state in _TERMINAL or self.state is SessionState.IDLE: raise ValueError(f"cannot fail from {self.state}") self.state = SessionState.FAILED self.clear_content()
def reset(self) -> None: """Clear a completed session so the next trigger can begin a new one.""" if self.state not in _TERMINAL and self.state is not SessionState.IDLE: raise ValueError(f"cannot reset an active session from {self.state}") self.clear_content() self.state = SessionState.IDLE
def clear_content(self) -> None: self.audio = self.transcript = self.context = self.prompt = self.output = None

from __future__ import annotations

import os
import subprocess
import sys
import textwrap
import unittest
from pathlib import Path


class LocalClientOfflineAcceptanceTests(unittest.TestCase):
    def test_loopback_asr_and_cleanup_clients_complete_with_external_sockets_blocked(self) -> None:
        script = textwrap.dedent(
            """
            import json
            import socket
            import tempfile
            import threading
            from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
            from pathlib import Path

            from dictate.asr import WhisperServer
            from dictate.cleanup import OllamaClient
            from dictate.config import Preferences
            from dictate.offline import install_loopback_only_guard
            from dictate.platform.base import Capability, PlatformAdapter, TargetSnapshot
            from dictate.service import DictationService, RecoveryStore

            SENTINEL = "offline-private-sentinel"
            class Handler(BaseHTTPRequestHandler):
                def log_message(self, format, *args): pass
                def do_GET(self):
                    self.send_response(200); self.end_headers()
                def do_POST(self):
                    body = self.rfile.read(int(self.headers["Content-Length"]))
                    if self.path == "/inference":
                        if not body.startswith(b"RIFF"): raise SystemExit("ASR did not receive in-memory WAV")
                        payload = {"text": SENTINEL}
                    elif self.path == "/api/generate":
                        request = json.loads(body)
                        if SENTINEL not in request["prompt"]: raise SystemExit("cleanup did not receive local transcript")
                        payload = {"response": "polished"}
                    else:
                        self.send_error(404); return
                    self.send_response(200); self.send_header("Content-Type", "application/json"); self.end_headers()
                    self.wfile.write(json.dumps(payload).encode())

            class Platform(PlatformAdapter):
                target = TargetSnapshot("app", "window", "field")
                def microphone_permission(self): return Capability(True)
                def trigger_permission(self): return Capability(True)
                def placement_permission(self): return Capability(True)
                def context_permission(self): return Capability(False)
                def snapshot_target(self): return self.target
                def read_context(self, target, limit): return None
                def target_matches(self, target): return target == self.target
                def insert_text(self, target, text): self.inserted = text; return True
                def start_hotkey(self, *args): pass
                def stop_hotkey(self): pass
                def recovery_instruction(self): return "recover"

            class Recorder:
                def start(self): pass
                def stop(self): return b"\\x00\\x00"
                def discard(self): pass

            server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
            thread = threading.Thread(target=server.serve_forever, daemon=True); thread.start()
            endpoint = f"http://127.0.0.1:{server.server_port}"
            install_loopback_only_guard()
            try:
                socket.create_connection(("8.8.8.8", 53), timeout=0.1)
            except OSError:
                pass
            else:
                raise SystemExit("external socket was not blocked")
            with tempfile.TemporaryDirectory() as directory:
                platform = Platform()
                service = DictationService(
                    Preferences(asr_endpoint=endpoint, ollama_endpoint=endpoint), platform, Recorder(),
                    WhisperServer(endpoint), OllamaClient(endpoint, "qwen3:4b-instruct-2507-q4_K_M"), recovery=RecoveryStore(),
                )
                service.press(); service.release()
                if platform.inserted != "polished": raise SystemExit("local clients did not complete pipeline")
                if list(Path(directory).iterdir()): raise SystemExit("pipeline persisted an artifact")
            server.shutdown(); server.server_close()
            print("local-clients-offline-pass")
            """
        )
        source_root = str(Path(__file__).parents[2] / "src")
        environment = os.environ | {"PYTHONPATH": source_root}
        result = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True, env=environment, check=False)
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertEqual("local-clients-offline-pass\n", result.stdout)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import contextlib
import io
import unittest
from unittest.mock import patch

from dictate.audio import AudioInputDevice
from dictate.service import ReadinessResult


class CliTests(unittest.TestCase):
    def invoke(self, arguments: list[str]) -> tuple[int, str, str]:
        from dictate.cli import main

        stdout, stderr = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            result = main(arguments)
        return result, stdout.getvalue(), stderr.getvalue()

    @patch("dictate.cli.list_input_devices", return_value=(AudioInputDevice("7", "Built-in Microphone"),))
    def test_devices_lists_identifiers_without_recording(self, _devices: object) -> None:
        result, stdout, stderr = self.invoke(["devices"])
        self.assertEqual(0, result)
        self.assertEqual("7\tBuilt-in Microphone\n", stdout)
        self.assertEqual("", stderr)

    @patch("dictate.cli.check_readiness", return_value=ReadinessResult((), ("destination context: grant-accessibility",)))
    @patch("dictate.cli.current_platform", return_value=object())
    def test_setup_reports_ready_with_optional_context_limitation(self, _platform: object, _readiness: object) -> None:
        result, stdout, stderr = self.invoke(["setup"])
        self.assertEqual(0, result)
        self.assertEqual("setup: ready\n", stdout)
        self.assertIn("limitation: destination context: grant-accessibility", stderr)

    @patch("dictate.cli.check_readiness", return_value=ReadinessResult(("microphone: connect-a-microphone",), ()))
    @patch("dictate.cli.current_platform", return_value=object())
    def test_doctor_returns_nonzero_content_free_required_failure(self, _platform: object, _readiness: object) -> None:
        result, stdout, stderr = self.invoke(["doctor"])
        self.assertEqual(1, result)
        self.assertEqual("", stdout)
        self.assertEqual("doctor: not ready: microphone: connect-a-microphone\n", stderr)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations
import tempfile import unittest from pathlib import Path
from dictate.config import Preferences, load_preferences, save_preferences from dictate.dictionary import load_dictionary, merge_dictionaries from dictate.session import DictationSession, SessionState
class ConfigDictionarySessionTests(unittest.TestCase): def test_defaults_use_natural_system_microphone_and_blessed_trigger(self) -> None: with tempfile.TemporaryDirectory() as directory: preferences = load_preferences(Path(directory) / "missing.toml") self.assertEqual("Natural", preferences.style) self.assertEqual("system-default", preferences.microphone) self.assertEqual("right_alt", preferences.trigger)
def test_preferences_are_written_as_readable_toml_atomically(self) -> None: with tempfile.TemporaryDirectory() as directory: path = Path(directory) / "preferences.toml" saved = Preferences(style="Technical", microphone="device-1") save_preferences(path, saved) self.assertEqual(saved, load_preferences(path)) self.assertFalse(list(Path(directory).glob(".preferences.toml.*")))
def test_project_dictionary_overrides_global_spelling(self) -> None: with tempfile.TemporaryDirectory() as directory: path = Path(directory) / "dictionary.txt" path.write_text("Ollama\nDictate\n", encoding="utf-8") global_terms = load_dictionary(path) self.assertEqual(("Dictate", "OLLAMA"), merge_dictionaries(global_terms, {"ollama": "OLLAMA"}))
def test_duplicate_dictionary_term_reports_local_line_numbers(self) -> None: with tempfile.TemporaryDirectory() as directory: path = Path(directory) / "dictionary.txt" path.write_text("Ollama\nOLLAMA\n", encoding="utf-8") with self.assertRaisesRegex(ValueError, "lines 1 and 2"): load_dictionary(path)
def test_every_terminal_state_clears_content(self) -> None: for terminal in (SessionState.INSERTED, SessionState.RECOVERY, SessionState.FAILED): with self.subTest(terminal=terminal): session = DictationSession( state=SessionState.VALIDATING_TARGET, audio=b"audio", transcript="transcript", context="context", prompt="prompt", output="output", ) session.transition(terminal) self.assertEqual(terminal, session.state) self.assertEqual((None, None, None, None, None), (session.audio, session.transcript, session.context, session.prompt, session.output))
def test_failure_clears_content(self) -> None: session = DictationSession(state=SessionState.RECORDING, audio=b"audio", transcript="transcript") session.fail() self.assertEqual(SessionState.FAILED, session.state) self.assertIsNone(session.audio) self.assertIsNone(session.transcript)
if __name__ == "__main__": unittest.main()
